import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"QoS Demo","description":"","frontmatter":{"title":"QoS Demo","date":"2026-04-02T00:00:00.000Z","updated":"2026-04-03T00:00:00.000Z","tags":["NFS","QoS","Ceph","TLS","high availability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/QoS_Demo.md","filePath":"posts/2026/QoS_Demo.md","lastUpdated":1780459816000}'),i={name:"posts/2026/QoS_Demo.md"};function l(n,e,d,h,s,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲由 Sha 主讲，介绍了 Ceph NFS 即将推出的四项增强功能：QoS（Quality of Service）、TLS 传输层安全、BYOK（Bring Your Own Key，自带密钥）以及 NFS active-active 高可用支持。演讲者在 Ceph 存储团队工作约一年半，专注于 NFS 相关功能开发。</p><h2 id="背景与问题" tabindex="-1">背景与问题 <a class="header-anchor" href="#背景与问题" aria-label="Permalink to &quot;背景与问题&quot;">​</a></h2><p>当前大多数组织运行多租户环境，面临以下核心挑战：</p><ul><li><strong>性能不可预测</strong>：租户之间无法保证公平的带宽分配</li><li><strong>通信安全</strong>：NFS 客户端与服务端之间缺乏加密保护（明文流量）</li><li><strong>密钥管理受限</strong>：客户无法自主控制数据加密密钥</li><li><strong>高可用瓶颈</strong>：active-passive 架构在故障切换时需要人工干预</li></ul><p>这四项新功能分别针对上述问题提供解决方案。</p><h2 id="功能一-qos-quality-of-service" tabindex="-1">功能一：QoS（Quality of Service） <a class="header-anchor" href="#功能一-qos-quality-of-service" aria-label="Permalink to &quot;功能一：QoS（Quality of Service）&quot;">​</a></h2><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><p>多租户环境中的&quot;noisy neighbor&quot;问题：某个备份任务突然占用大量带宽，导致关键业务工作负载带宽不足。</p><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h3><p>QoS 提供两种控制维度：</p><ul><li><strong>带宽控制（Bandwidth Control）</strong>：限制最大吞吐量（Mbps）</li><li><strong>IOPS 控制</strong>：限制每秒输入输出操作数</li></ul><h3 id="qos-类型" tabindex="-1">QoS 类型 <a class="header-anchor" href="#qos-类型" aria-label="Permalink to &quot;QoS 类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Per Share</td><td>限制设置在 export 级别，每个 export 有独立上限，但不保证客户端级别公平性</td></tr><tr><td>Per Client</td><td>限制设置在客户端级别，不限制 export 总量</td></tr><tr><td>Per Share Per Client</td><td>双层限制，同时在 export 和客户端两个层面设置上限</td></tr></tbody></table><h3 id="配置层级" tabindex="-1">配置层级 <a class="header-anchor" href="#配置层级" aria-label="Permalink to &quot;配置层级&quot;">​</a></h3><ul><li><strong>Cluster 级别</strong>：全局 QoS，适用于该 NFS cluster 下所有 export，需先启用才能配置 export 级别</li><li><strong>Export 级别</strong>：可覆盖 cluster 级别的值，针对特定 export 单独配置</li></ul><h3 id="演示结果" tabindex="-1">演示结果 <a class="header-anchor" href="#演示结果" aria-label="Permalink to &quot;演示结果&quot;">​</a></h3><ul><li>无 QoS 限制时：写入带宽约 115 Mbps</li><li>启用 cluster 级别 QoS（50 Mbps）后：实测约 48.4 Mbps</li><li>进一步设置 export 级别 QoS（30 Mbps）后：实测约 29.8 Mbps</li></ul><p>QoS 功能有效保障了多租户间的带宽公平性，防止关键工作负载饥饿。</p><h2 id="功能二-tls-传输层安全" tabindex="-1">功能二：TLS 传输层安全 <a class="header-anchor" href="#功能二-tls-传输层安全" aria-label="Permalink to &quot;功能二：TLS 传输层安全&quot;">​</a></h2><h3 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h3><p>TLS 为 NFS 客户端与服务端之间的网络通信提供加密保护，具备：</p><ul><li><strong>保密性</strong>：加密所有传输数据</li><li><strong>完整性</strong>：检测传输过程中的数据篡改</li><li><strong>认证</strong>：可选的双向认证（mTLS）</li></ul><h3 id="证书来源配置" tabindex="-1">证书来源配置 <a class="header-anchor" href="#证书来源配置" aria-label="Permalink to &quot;证书来源配置&quot;">​</a></h3><p>支持三种证书来源（<code>certificate_source</code>）：</p><ul><li><code>inline</code>：直接在 spec 中指定 SSL key、SSL cert 和 CA cert</li><li><code>cephadm_signed</code>：由 cephadm 自动生成证书</li><li><code>reference</code>：引用 cert manager 中存储的证书（上一版本引入的功能）</li></ul><h3 id="其他配置项" tabindex="-1">其他配置项 <a class="header-anchor" href="#其他配置项" aria-label="Permalink to &quot;其他配置项&quot;">​</a></h3><ul><li><strong>KTLS（Kernel TLS）</strong>：在内核层面完成加密解密，适合性能敏感型工作负载；若硬件加速可用则效果更佳</li><li><strong>TLS 调试模式</strong>：可指定最低 TLS 版本和 cipher 套件</li></ul><h3 id="export-安全级别" tabindex="-1">Export 安全级别 <a class="header-anchor" href="#export-安全级别" aria-label="Permalink to &quot;Export 安全级别&quot;">​</a></h3><ul><li><code>TLS</code>：仅客户端认证</li><li><code>mTLS</code>：客户端与服务端双向认证</li></ul><p>若 cluster 级别启用了 TLS，export 未单独指定时，客户端可使用 TLS 或 mTLS 挂载；若 export 明确设置为 TLS，则客户端必须使用 TLS 才能挂载。</p><h3 id="演示结果-1" tabindex="-1">演示结果 <a class="header-anchor" href="#演示结果-1" aria-label="Permalink to &quot;演示结果&quot;">​</a></h3><ul><li>未携带 TLS 证书挂载启用了 TLS 的 export：返回&quot;Operation not permitted&quot;</li><li>携带客户端证书挂载 mTLS export：成功建立连接，NFS 日志显示&quot;TLS connection established，MTLS=1&quot;</li></ul><h2 id="功能三-byok-bring-your-own-key-自带密钥" tabindex="-1">功能三：BYOK（Bring Your Own Key，自带密钥） <a class="header-anchor" href="#功能三-byok-bring-your-own-key-自带密钥" aria-label="Permalink to &quot;功能三：BYOK（Bring Your Own Key，自带密钥）&quot;">​</a></h2><h3 id="功能说明-1" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明-1" aria-label="Permalink to &quot;功能说明&quot;">​</a></h3><p>允许客户通过 NFS 访问加密存储，加密解密在 CephFS 层完成。客户可完全掌控静态数据的加密密钥，NFS 与外部 KMS（Key Management Server）集成，通信基于 mTLS 保证安全。</p><h3 id="限制条件" tabindex="-1">限制条件 <a class="header-anchor" href="#限制条件" aria-label="Permalink to &quot;限制条件&quot;">​</a></h3><ul><li>仅支持 CephFS export（不支持其他类型）</li><li>加密粒度为 subvolume 级别</li><li>每个 export 可使用不同的加密密钥，实现租户数据隔离</li><li>创建 export 前，对应子目录必须为空</li><li>加密密钥一旦设置，不可更改</li></ul><h3 id="配置方式" tabindex="-1">配置方式 <a class="header-anchor" href="#配置方式" aria-label="Permalink to &quot;配置方式&quot;">​</a></h3><p>在 NFS spec 中指定：</p><ul><li><code>kmip_cert</code>、<code>kmip_key</code>：与 KMS 服务器通信的客户端证书</li><li><code>kmip_cacert</code>：KMS 服务器的 CA 证书</li><li><code>kmip_hostlist</code>：支持配置多个 KMS 服务器地址（用于 HA）</li><li>创建 export 时指定 <code>kmip_key_id</code></li></ul><p>NFS 服务通过 <code>libkmip</code> 库与外部 KMS 服务器通信获取实际加密密钥。</p><h3 id="演示结果-2" tabindex="-1">演示结果 <a class="header-anchor" href="#演示结果-2" aria-label="Permalink to &quot;演示结果&quot;">​</a></h3><p>演示使用 IBM GKLM 作为 KMS 服务器：</p><ul><li>通过 NFS 挂载后，文件内容以明文可见</li><li>通过 CephFS FUSE 直接挂载同一 subvolume 后，文件名和目录名均显示为加密状态</li></ul><h2 id="功能四-nfs-active-active-高可用增强" tabindex="-1">功能四：NFS Active-Active 高可用增强 <a class="header-anchor" href="#功能四-nfs-active-active-高可用增强" aria-label="Permalink to &quot;功能四：NFS Active-Active 高可用增强&quot;">​</a></h2><h3 id="现有架构" tabindex="-1">现有架构 <a class="header-anchor" href="#现有架构" aria-label="Permalink to &quot;现有架构&quot;">​</a></h3><p>多个 NFS（Ganesha）服务运行在 HAProxy ingress 后端，客户端通过虚拟 IP（VIP，由 Keepalived 维护）访问，HAProxy 将请求转发至后端 NFS 服务器，实现 load balancing。</p><h3 id="现有问题" tabindex="-1">现有问题 <a class="header-anchor" href="#现有问题" aria-label="Permalink to &quot;现有问题&quot;">​</a></h3><p>当某个后端 NFS 服务器宕机时，HAProxy 会将该服务器的客户端请求转发至其他服务器。但 NFS 协议的 client lease 机制不允许由另一台服务器接管客户端状态，导致客户端永久挂起，必须手动重新挂载。</p><h3 id="增强方案" tabindex="-1">增强方案 <a class="header-anchor" href="#增强方案" aria-label="Permalink to &quot;增强方案&quot;">​</a></h3><ol><li><p><strong>HAProxy Stick Table</strong>：在 HAProxy 中维护客户端与服务器的映射关系，多个 HAProxy 实例之间共享该映射。即使 active HAProxy 宕机，其他实例也能继续维持客户端连接，避免客户端挂起。</p></li><li><p><strong>NFS Daemon Colocation（守护进程同址部署）</strong>：当某台主机上的 NFS 服务宕机后重新上线时，允许在现有主机上重新启动该服务（无需额外主机），HAProxy 无需更改服务器映射，客户端可无感知地继续服务。</p></li><li><p><strong>HAProxy 健康检查增强</strong>：改进健康检查机制以更好地维护客户端-服务器映射。</p></li></ol><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>解决的问题</th></tr></thead><tbody><tr><td>QoS</td><td>多租户带宽公平性，防止 noisy neighbor，保障关键工作负载</td></tr><tr><td>TLS</td><td>传输层加密，防止明文流量，支持双向认证</td></tr><tr><td>BYOK</td><td>静态数据加密，客户自主控制密钥，与外部 KMS 集成</td></tr><tr><td>Active-Active HA</td><td>消除故障切换时的人工干预，提升 high availability</td></tr></tbody></table><p>以上功能目前尚未合并至上游，将在后续版本中发布。演讲者感谢 NFS 团队的实现工作。</p>',55)])])}const S=a(i,[["render",l]]);export{p as __pageData,S as default};
